"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4267],{35974:function(e,n,a){a.d(n,{C:function(){return i}});var o=a(57437);a(2265);var t=a(90535),r=a(94508);let s=(0,t.j)("inline-flex items-center rounded-md border px-2 py-0.5 text-xs font-medium transition-colors",{variants:{variant:{default:"border-transparent bg-brand-50 text-brand-700",secondary:"border-transparent bg-slate-100 text-slate-700",outline:"border-slate-200 text-slate-700",success:"border-transparent bg-emerald-50 text-emerald-700",warning:"border-transparent bg-amber-50 text-amber-700",danger:"border-transparent bg-red-50 text-red-700",accent:"border-transparent bg-cyan-50 text-cyan-700",levelA:"border-transparent bg-red-100 text-red-700",levelB:"border-transparent bg-orange-100 text-orange-700",levelC:"border-transparent bg-slate-100 text-slate-700",levelD:"border-transparent bg-slate-100 text-slate-500"}},defaultVariants:{variant:"default"}});function i(e){let{className:n,variant:a,...t}=e;return(0,o.jsx)("div",{className:(0,r.cn)(s({variant:a}),n),...t})}},23947:function(e,n,a){a.d(n,{BE:function(){return o}});let o=[{id:"agent_market",name:"市场咨询 Agent",group:"A",groupName:"营销前端",icon:"Globe2",shortDesc:"国别 / 行业 / 趋势的实时智囊",longDesc:"聚合全球 140+ 国家的家居装修市场数据，结合本地宏观经济与政策动态，回答任何与海外市场相关的问题。",serveFor:["营销总监","投手","PM","运营"],module:"渠道管理",dataSource:["全球海关数据","TikTok / Meta 行业洞察","Google Trends","本平台历史成交数据"],capabilities:["市场容量分析","竞品分析","投放区域推荐","本地化策略"],accent:"accent",metrics:[{label:"数据覆盖国家",value:"140+"},{label:"日均查询",value:"1.2k"},{label:"建议采纳率",value:"73%"}],presetQuestions:[{question:"加拿大泛家居市场怎么样？",answer:"**加拿大泛家居市场（2026 上半年）**\n\n- 市场规模：约 USD 23.4B，年增速 +6.8%\n- 主力品类：厨房整装（占 28%）、卫浴改造（21%）、地板（17%）\n- 高需求城市：多伦多、温哥华、卡尔加里、蒙特利尔\n- 新移民业主占比：32%（同比 +5%），他们更接受全屋一站式方案\n- 平均客单价：USD 24,800\n\n**敬城建议**：本月加大多伦多 GTA 区域 TikTok 投放预算 20%，匹配 pre-construction 新房交付高峰。"},{question:"印度市场询盘质量为什么下降？",answer:'印度市场询盘质量下降的核心原因：\n\n1. **季节因素**：5 月进入印度雨季前的"低决策期"，业主多采取观望\n2. **当地政策**：部分邦的进口家居关税预期调整，业主推迟下单\n3. **创意疲劳**：当前 TikTok 主推素材已投放 8 周，CTR 下滑 18%\n\n建议：本周缩减印度市场投放预算 30%，待 6 月雨季后回升。同时让创意发现 Agent 生成 5 条本地化新素材。'},{question:"中东市场哪个国家潜力最大？",answer:"**中东市场潜力排名（2026 H1）**：\n\n1. **\uD83C\uDDE6\uD83C\uDDEA 阿联酋**：豪宅项目密集，平均客单价 USD 48k\n2. **\uD83C\uDDF8\uD83C\uDDE6 沙特**：Vision 2030 驱动民用建筑投资，增长最快\n3. **\uD83C\uDDF0\uD83C\uDDFC 科威特**：高净值业主多，复购率高\n\n推荐重点：阿联酋 Builder 市场，他们每月有 3-5 个独立别墅项目。"},{question:"TikTok 在欧洲投放成本上升的原因？",answer:"欧洲 TikTok 投放成本上升 18% 的主要原因：\n\n- 欧盟 DSA 法规收紧广告竞价机制\n- Q2 进入欧洲购物旺季，行业整体竞价上扬\n- 当地家居品牌加大投放力度\n\n建议转向 Instagram Reels + YouTube Shorts，预计可降低 25% CAC。"},{question:"东南亚 Builder 市场怎么打？",answer:'东南亚 Builder 市场（新加坡 / 马来 / 菲律宾）打法：\n\n1. 主攻"项目级整装包"而非单品\n2. 提供 Builder 专属定价（约整装价 -20%）\n3. 关键打开式：通过本地设计师推荐\n4. 物流：建议 LCL 海运 + 本地仓中转，缩短交付到 30 天内'}]},{id:"agent_creative",name:"创意发现 Agent",group:"A",groupName:"营销前端",icon:"Wand2",shortDesc:"10 秒生成爆款素材脚本",longDesc:"基于平台百万级素材效果数据 + 当前热点趋势，为投手与素材组生成可直接拍摄的脚本与分镜。",serveFor:["投手","素材组","运营"],module:"渠道管理",dataSource:["TikTok 全球趋势","本平台素材效果库","竞品爆款脚本"],capabilities:["脚本生成","分镜建议","Hook 句库","爆款素材衍生"],accent:"amber",metrics:[{label:"本月生成脚本",value:"238"},{label:"脚本转化率",value:"31%"},{label:"Hook 库容量",value:"2.4k"}],presetQuestions:[{question:"给我一条北美厨房整装的 TikTok 脚本",answer:'**Hook（0-3s）**：手指划过老旧厨房 → "If your kitchen looks like this, you\'re losing $5,000 a year"\n\n**Body（3-15s）**：3 个对比镜头（脏乱→整洁 / 收纳挤压→隐藏式收纳 / 黄光→白光）\n\n**CTA（15-20s）**："Tap to get your 96\\" island quote in 60 seconds — Toronto family just saved $4,200"\n\n**音乐**：Tension Build 起 / Smooth drop 收\n**热度**：相似结构脚本本月平均 CTR 4.2%'},{question:"帮我衍生 5 条厨房岛台的 Hook 句",answer:'**5 条岛台 Hook 句**：\n\n1. "Your kitchen island is too small. Here\'s why 96\\" changes everything."\n2. "I designed 200 kitchens. The biggest mistake? An island under 90 inches."\n3. "Toronto homeowners are obsessed with this island length."\n4. "Replace your old island for $4,800. Your new dinner parties begin here."\n5. "If your contractor told you 72\\" is enough, watch this first."'},{question:"中东豪宅项目用什么脚本结构？",answer:"**中东豪宅脚本结构（适用阿联酋 / 沙特）**：\n\n- Hook：富有质感的镜头，避免直接价格信息\n- Body：强调材质、工艺、定制感\n- CTA：通过 WhatsApp 一对一对接\n\n关键词：marble \xb7 custom \xb7 bespoke \xb7 concierge"},{question:"印度市场素材最常踩的坑是？",answer:"印度市场常见踩坑点：\n\n1. 价格直接展示美元 / 欧元 → 应展示 INR\n2. 全屋方案过大，业主预算敏感 → 应拆分单空间小切片\n3. 模特白人为主 → 应使用本地化模特\n4. 配乐欧美流行 → 应用宝莱坞 / Punjabi remix"}]},{id:"agent_content",name:"内容创作 Agent",group:"A",groupName:"营销前端",icon:"Pencil",shortDesc:"营销文案 / 落地页 / 邮件营销",longDesc:"为投手提供长短文案、A/B 测试句库、邮件 EDM、落地页骨架等所有营销文字内容。",serveFor:["投手","Landing Page 设计师","EDM 负责人"],module:"渠道管理",dataSource:["历史文案表现","落地页转化数据","邮件打开 / 点击数据"],capabilities:["短文案","长文案","A/B 句库","EDM","Landing Copy"],accent:"brand",metrics:[{label:"本月生成文案",value:"1,247"},{label:"采用率",value:"68%"}],presetQuestions:[{question:"帮我写一段加拿大别墅业主的开场白",answer:"Hi {Name}, this is Mike from GEORGE — I noticed you're working on a new pre-construction home in the Toronto area. We've helped 40+ Canadian homeowners design and install full-house renovation packages (kitchen, bath, flooring) within 8–10 weeks.\n\nIf you have a floor plan or moodboard, I'd be happy to send back a no-obligation budget breakdown so you can plan your timeline. What stage are you currently at?"},{question:"给我一封报价跟进邮件",answer:"Subject: Quick check-in on your kitchen quote \uD83C\uDF73\n\nHi {Name},\n\nIt's been a few days since we sent over the kitchen + 2-bath proposal. I wanted to check if anything is unclear or if you'd like me to adjust the materials list to fit your timeline.\n\nA couple of our recent Toronto customers also asked about phased delivery — happy to walk you through that option if it helps.\n\nLet me know a good time to chat, even 10 minutes works.\n\nWarmly,\nMike"}]},{id:"agent_ads",name:"广告投放 Agent",group:"A",groupName:"营销前端",icon:"Target",shortDesc:"全渠道预算与定向自动优化",longDesc:"实时监控 TikTok / Meta / YouTube / Google 等渠道效果，给出预算分配、定向调整、出价策略建议。",serveFor:["投手","营销总监"],module:"渠道管理",dataSource:["广告平台 API","归因模型","成交回流数据"],capabilities:["预算分配","定向优化","出价策略","异常预警"],accent:"brand",metrics:[{label:"本月监控账户",value:"47"},{label:"节约预算",value:"$28k"}],presetQuestions:[{question:"本周 TikTok 投放应该怎么调？",answer:"本周 TikTok 投放建议：\n\n1. **多伦多 GTA**：CTR 4.5% / ROAS 5.6 → 预算 +20%（约 $2,800）\n2. **温哥华**：CTR 2.1% → 暂停效果差的 2 条素材\n3. **悉尼**：CVR 上升 30% → 切换至高出价竞价\n4. 整体策略：本周加大北美投入，缩减英国 15%"},{question:"印度市场要不要继续投？",answer:"建议本周缩减印度 TikTok 投放 30%，转移预算到 Instagram。原因：\n\n- 询盘质量下降（CAC 上升 24%）\n- TikTok 在印度的 Builder 客群获取能力弱于 IG\n- IG Reels 同期 CAC 仅 $42\n\n6 月雨季后再恢复 TikTok。"}]},{id:"agent_insight",name:"数据洞察 Agent",group:"A",groupName:"营销前端",icon:"Sparkles",shortDesc:"周度营销复盘 + 趋势预测",longDesc:"每周自动生成营销复盘报告，识别异常、归因卡点、推荐下周动作。",serveFor:["营销总监","管理层"],module:"渠道管理",dataSource:["全渠道数据","客户漏斗","财务回款"],capabilities:["归因分析","异常预警","战略建议","周报自动生成"],accent:"brand",presetQuestions:[{question:"本周营销表现如何？",answer:"**本周营销表现摘要（第 19 周）**\n\n- 总询盘：1,247 ↑ +18%\n- 平均 CAC：$103 ↓ -8%\n- 成交订单：89（金额 $1.24M）\n- 明星渠道：TikTok（ROAS 5.1）\n- 待优化：YouTube（ROAS 1.5）\n\n**3 条洞察**：\n1. TikTok 已连续 4 周成为 ROAS 第一，建议结构性增加预算 25%\n2. YouTube 前 3 秒留存率仅 38%，需优化 Hook\n3. 印度市场询盘下滑明显（-22%），建议季节性收缩"}]},{id:"agent_sales",name:"AI 业务员",group:"B",groupName:"销售一线",icon:"MessageCircle",shortDesc:"首响接待 / 6 维信息收集 / 自动派单",longDesc:"客户从渠道进入 WhatsApp 的第一接待人。3 秒内首响，自动收集 6 维信息，输出会话总结。",serveFor:["PM","PM 助理"],module:"SCRM",dataSource:["历史对话语料","公司话术库","派单算法"],capabilities:["3 秒首响","6 维信息收集","意图识别","派单建议"],accent:"success",metrics:[{label:"平均首响",value:"2.8s"},{label:"6 维收齐率",value:"84%"},{label:"派单建议采纳",value:"91%"}],presetQuestions:[{question:"AI 业务员收集哪 6 维信息？",answer:"AI 业务员对每个进站客户自动收集 6 维信息：\n\n1. **图纸** —— 户型 / 改造范围\n2. **清单** —— 想做的品类（厨房 / 卫浴 / 地板...）\n3. **客户身份** —— 业主 / Builder / 设计师 / 中介\n4. **项目阶段** —— 期房 / 在建 / 已入住...\n5. **国家** —— 物流与定价分区\n6. **类型** —— 住宅 / 别墅 / 商业 / 工程\n\n6 维收齐后，自动评分 + ABCD 分级 + 推荐派单。"},{question:"派单算法是怎么决定推荐哪个 PM？",answer:"PM 派单算法基于 5 个因子加权：\n\n- **国家匹配**（30%）：该 PM 历史成交客户所在国家\n- **品类匹配**（20%）：该 PM 主打品类\n- **语言能力**（15%）：原生 / 流利 / 一般\n- **当前负载**（20%）：客户池容量与紧急度\n- **历史评分**（15%）：该 PM 综合评分\n\n例如 Kanchan：加拿大 + 别墅 + 英语母语 → Mike Liu（综合分 92）胜出。"}]},{id:"agent_top_company",name:"AI 公司销冠",group:"B",groupName:"销售一线",icon:"Trophy",shortDesc:"公司级最佳实践沉淀",longDesc:'汇聚全公司 Top 10% PM 的话术、节奏、谈判技巧，形成公司级"销冠人格"。',serveFor:["PM 助理","新人 PM"],module:"SCRM",dataSource:["公司知识库","顶级 PM 历史会话","成交案例"],capabilities:["话术库","对策模板","议价节奏","成交话术"],accent:"amber",presetQuestions:[{question:'客户说"价格太贵了"，怎么回？',answer:'**公司销冠话术（议价 - 价格异议）**：\n\n第一步：先共情，不急于让价：\n"I totally understand — for a project this size, every dollar matters. Let me walk you through what\'s actually inside the package."\n\n第二步：拆解价值：\n- 材料 / 工艺 / 服务三段拆分\n- 突出非显性成本（物流 / 售后 / 设计）\n\n第三步：给"软让步"：\n- 不直接降总价\n- 提供"增值项打包"（如免费 3D 渲染、延长保修）\n\n第四步：制造紧迫感：\n- 提及当前季度限定优惠或物流档期'}]},{id:"agent_top_dept",name:"AI 部门销冠",group:"B",groupName:"销售一线",icon:"Users",shortDesc:"部门级经验 + 主管复盘",longDesc:'聚合各部门主管复盘与部门 Top PM 的本地化策略，给出"部门视角"的建议。',serveFor:["部门 PM"],module:"SCRM",dataSource:["部门知识库","主管复盘","部门 Top PM 案例"],capabilities:["地域策略","本地化话术","部门最佳实践"],accent:"amber",presetQuestions:[{question:"加拿大别墅客户最常关注什么？",answer:"加拿大别墅客户关注点 Top 5（基于加拿大事业部 240 单复盘）：\n\n1. **冬季施工可行性**（68% 客户问到）\n2. **海运到温哥华 / 多伦多时效**（54%）\n3. **是否提供 VOC 环保认证**（48%）\n4. **能否提供 3D 渲染再下单**（42%）\n5. **付款是否支持 Wise / Interac**（38%）"}]},{id:"agent_top_personal",name:"AI 个人销冠",group:"B",groupName:"销售一线",icon:"User",shortDesc:"你的专属 AI 副驾",longDesc:"基于你过去的成功案例与个人风格，给出符合你气质的话术建议。",serveFor:["PM 本人"],module:"SCRM",dataSource:["个人历史会话","成交 / 流失复盘","个人偏好"],capabilities:["个性化话术","节奏建议","客户性格匹配"],accent:"amber",presetQuestions:[{question:"Kanchan 已读不回 48 小时，怎么破？",answer:'**基于你过去处理加拿大业主的成功经验**：\n\nKanchan 在第二轮报价后已读不回。你过去处理过类似的 William Brown / Brian Murphy，他们都是同样的"理性思考型"。\n\n推荐节奏：\n\n1. **今日 19:00（多伦多时间）**：发一条价值感强的信息，不催报价：\n   "Hey Kanchan, just remembered — one of our Toronto customers (similar pre-con size) just finalized their kitchen install last week. Let me share their before-after pic if you\'d like."\n\n2. **后日**：如仍未回复，发一条简短的语音（30s 内）—— 你过去对加拿大客户的语音回复率高于平均 35%。\n\n3. **第 4 天**：如再未回复，建议转电话沟通。'}]},{id:"agent_pm",name:"AI 项目经理",group:"C",groupName:"项目交付",icon:"ClipboardList",shortDesc:"项目阶段识别 / 健康度评估",longDesc:"自动识别项目所处阶段，给出推进建议、预警卡点、生成下一步动作。",serveFor:["PM","部门主管"],module:"项目管理",dataSource:["项目阶段数据","客户行为","时间线事件"],capabilities:["阶段识别","健康度评估","卡点预警","动作建议"],accent:"brand",presetQuestions:[{question:"Kanchan 项目当前状态？",answer:"**Kanchan Rajput \xb7 多伦多别墅整装**\n\n- 当前阶段：需求挖掘（2/8）\n- 已用时：14 天（行业均值 12 天）\n- 健康度：✓ 正常\n- 6 维信息：5/6 已收齐（缺客户身份正式确认）\n- 下一步建议：在 3 天内完成方案确认并进入报价阶段\n- 风险提示：客户已读不回 48h，建议主动唤醒"}]},{id:"agent_qa",name:"AI 质检员",group:"C",groupName:"项目交付",icon:"ShieldCheck",shortDesc:"会话质检 / 项目交付质检",longDesc:"自动质检 PM 会话合规性、报价合理性、项目交付完整度。",serveFor:["部门主管","管理层"],module:"项目管理",dataSource:["会话记录","报价数据","交付记录"],capabilities:["合规检查","话术质检","交付验收"],accent:"danger",presetQuestions:[{question:"本周需要质检的会话有多少？",answer:"本周共发现 12 条需要主管关注的会话：\n\n- **价格异议处理不当**：4 条\n- **承诺超出权限**：2 条\n- **响应时长超标**：6 条\n\n建议优先 review 编号 #2341 / #2358 / #2402 这三条。"}]},{id:"agent_translate",name:"AI 翻译",group:"D",groupName:"通用能力",icon:"Languages",shortDesc:"实时多语种翻译（含中东 / 印地等）",longDesc:"覆盖 47 种语言，针对家居装修行业进行术语优化，支持 WhatsApp 实时翻译。",serveFor:["全员"],module:"SCRM / 全模块",dataSource:["行业术语库","PM 修正记录"],capabilities:["实时翻译","术语优化","语气匹配"],accent:"accent",presetQuestions:[{question:'把"哑光黑拉手"翻译成阿拉伯语',answer:"مقابض سوداء غير لامعة (matte black handles)\n\n该翻译已通过迪拜本地 PM 校对，是中东市场标准用法。"}]},{id:"agent_aigc",name:"AIGC 设计",group:"D",groupName:"通用能力",icon:"Palette",shortDesc:"图纸 → 3D 效果图 / 多风格切换",longDesc:"接入 AI 云绘，PM 上传客户图纸后 60 秒内生成 3 套不同风格的 3D 效果图。",serveFor:["PM"],module:"SCRM",dataSource:["客户图纸","材料库","风格库"],capabilities:["3D 渲染","风格切换","材质替换","对比图生成"],accent:"brand",presetQuestions:[{question:"为 Kanchan 生成的 3D 图能改风格吗？",answer:"可以！当前为白色 Shaker 风格。一键可切换至：\n\n- **现代极简**（Matte panel + Handle-less）\n- **工业风**（Black metal + Wood）\n- **过渡风**（Mixed material）\n\n生成时间：约 60 秒 / 风格。"}]}]}}]);